import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/ChatSidebar.css";

const ChatSidebar = ({ user, onSelectConversation }) => {
  const [conversations, setConversations] = useState([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState([]);

  useEffect(() => {
    const fetchConversations = async () => {
      try {
        const token = localStorage.getItem("token");
        const res = await axios.get("http://localhost:5000/api/conversations/" + user._id, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
        setConversations(res.data);
      } catch (err) {
        console.error("Error fetching conversations:", err);
      }
    };

    if (user?._id) {
      fetchConversations();
    }
  }, [user]);

  const handleSearch = async () => {
    try {
      const token = localStorage.getItem("token");
      const res = await axios.get(`http://localhost:5000/api/profile/search?username=${searchQuery}`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      // Only show users, not profiles
      const users = res.data.map((profile) => profile.userId);
      setSearchResults(users);
    } catch (err) {
      console.error("Error searching users:", err);
    }
  };

  const handleUserClick = async (recipientId) => {
    try {
      const token = localStorage.getItem("token");

      // Try to find existing conversation
      const res = await axios.get("http://localhost:5000/api/conversations/" + user._id, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      let existingConversation = res.data.find((conv) =>
        conv.members.includes(recipientId)
      );

      if (!existingConversation) {
        // No conversation exists, create one
        const createRes = await axios.post(
          "http://localhost:5000/api/conversations",
          {
            senderId: user._id,
            receiverId: recipientId,
          },
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );
        existingConversation = createRes.data;
      }

      // Notify parent
      onSelectConversation(existingConversation);
      setSearchResults([]);
      setSearchQuery("");
    } catch (err) {
      console.error("Error starting conversation:", err);
    }
  };

  return (
    <div className="chat-sidebar">
      <h4>Messages</h4>

      <input
        type="text"
        placeholder="Search by username"
        value={searchQuery}
        onChange={(e) => setSearchQuery(e.target.value)}
      />
      <button onClick={handleSearch}>Search</button>

      {searchResults.length > 0 && (
        <div className="search-results">
          {searchResults.map((usr) => (
            <div
              key={usr._id}
              className="search-result"
              onClick={() => handleUserClick(usr._id)}
            >
              {usr.username}
            </div>
          ))}
        </div>
      )}

      <div className="conversation-list">
        {conversations.length === 0 ? (
          <em>No conversations found.</em>
        ) : (
          conversations.map((conv, index) => (
            <div
              key={index}
              className="conversation-item"
              onClick={() => onSelectConversation(conv)}
            >
              {conv.members.find((id) => id !== user._id)}
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default ChatSidebar;
